import * as React from 'react';
import { Binding, Antimatter } from '@antimatterjs/react';

import { HorizontalAlignment, VerticalAlignment } from './Enums';

import './positron.css';

export interface IFrameworkElementProps
{
    HorizontalAlignment?: HorizontalAlignment | Binding,
    VerticalAlignment?: VerticalAlignment | Binding,
    IsVisible?: boolean | Binding,
    Margin?: string,
    OnClick?: (event: MouseEvent) => void,
    OnPointerDown?: (event: MouseEvent) => void
}

export interface IFrameworkElementState
{
    HorizontalAlignment?: HorizontalAlignment,
    VerticalAlignment?: VerticalAlignment,
    IsVisible?: boolean
}

export class FrameworkElement<
    P extends IFrameworkElementProps = {},
    S extends IFrameworkElementState = {}>
    extends React.Component<P, S>
{
    constructor(props)
    {
        super(props);
        Antimatter.InitializeComponent(this);
    }

    render()
    {
        if (this.state.IsVisible === false)
            return null;

        return (
            <div style={this.getCSSStyles()}
                onClick={this.props.OnClick
                    ? (event) => this.props.OnClick?.call(this, event.nativeEvent)
                    : undefined}
                onMouseDown={this.props.OnPointerDown
                    ? (event) => this.props.OnPointerDown?.call(this, event.nativeEvent)
                    : undefined}
                className={this.constructClasses()}>
                {this.renderElement()}
            </div>
        );
    }

    public InvalidateRender()
    {
        this.setState({});
    }

    protected SetValue(property: string, newValue: any): void
    {
        Antimatter.TargetChanged(this, property, newValue);
    }

    protected /* virtual */ renderElement(): JSX.Element | null
    {
        return null;
    }

    protected /* virtual */ getCSSStyles(): React.CSSProperties
    {
        return {
            margin: this.props.Margin
        };
    }

    protected /* virtual */ OnPropertyChanged(property: string, value: any)
    {
    }

    protected constructClasses(): string
    {
        let cls: string = 'amx-ptn-fe ';

        switch (this.state.HorizontalAlignment)
        {
            case HorizontalAlignment.Center:
                cls += "amx-ptn-ha-center ";
                break;
            case HorizontalAlignment.Left:
                cls += "amx-ptn-ha-left ";
                break;
            case HorizontalAlignment.Right:
                cls += "amx-ptn-ha-right ";
                break;
            case undefined:
            default:
                cls += "amx-ptn-ha-stretch ";
                break;
        }

        switch (this.state.VerticalAlignment)
        {
            case VerticalAlignment.Center:
                cls += "amx-ptn-va-center ";
                break;
            case VerticalAlignment.Top:
                cls += "amx-ptn-va-top ";
                break;
            case VerticalAlignment.Bottom:
                cls += "amx-ptn-va-bottom ";
                break;
            case VerticalAlignment.Stretch:
            case undefined:
                cls += "amx-ptn-va-stretch ";
                break;
        }

        return cls;
    }
}